SELECT ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@formatDate('create_time')} AS time,
       COUNT(*) AS customer_put_count
  FROM crm_owner_record
 WHERE deleted = 0
   AND biz_type = ${@com.group.antian.module.crm.enums.common.CrmBizTypeEnum@CRM_CUSTOMER.type}
   AND pre_owner_user_id IN

            #{userId}

   AND post_owner_user_id IS NULL
   AND create_time BETWEEN #{times[0],javaType=java.time.LocalDateTime} AND #{times[1],javaType=java.time.LocalDateTime}
 GROUP BY ${@com.group.antian.framework.mybatis.core.util.SqlDialectUtils@formatDate('create_time')}

